<script setup lang="ts">
import {onMounted,ref} from 'vue'; import {customersApi} from '@/api/customers'; import {treasuryApi} from '@/api/treasury'; import {salesInvoicesApi} from '@/api/salesInvoices'; import {salesReceiptsApi} from '@/api/salesReceipts'; import {useOrganizationContextStore} from '@/stores/organizationContext';
const org=useOrganizationContextStore(),customers=ref<any[]>([]),accounts=ref<any[]>([]),invoices=ref<any[]>([]),customerId=ref<number>(),accountId=ref<number>(),amount=ref(0),allocation=ref(0),invoiceId=ref<number>(),result=ref<any>(),error=ref('');
async function load(){customers.value=(await customersApi.list({size:100})).content;accounts.value=await treasuryApi.accounts();invoices.value=await salesInvoicesApi.list(org.companyId!,org.branchId!)}
async function create(){try{const r=await salesReceiptsApi.create({companyId:org.companyId!,branchId:org.branchId!,customerId:customerId.value!,amount:amount.value,paymentMethod:'CASH'},crypto.randomUUID());await salesReceiptsApi.allocate(r.id,invoiceId.value!,allocation.value);result.value=await salesReceiptsApi.confirm(r.id,accountId.value!)}catch(e:any){error.value=e?.message??'Receipt failed'}}
onMounted(async()=>{if(!org.context)await org.refresh();await load()})
</script>
<template><v-card rounded="xl"><v-card-title>Receipt / Settlement</v-card-title><v-card-text><v-select v-model="customerId" :items="customers" item-title="displayName" item-value="id" label="Customer"/><v-text-field v-model.number="amount" type="number" label="Receipt amount"/><v-select v-model="accountId" :items="accounts" item-title="name" item-value="id" label="Treasury account"/><v-select v-model="invoiceId" :items="invoices.filter(i=>i.customerId===customerId&&i.status==='ISSUED')" item-title="invoiceNumber" item-value="id" label="Eligible invoice"/><v-text-field v-model.number="allocation" type="number" label="Allocation amount"/><v-alert v-if="error" type="error">{{error}}</v-alert><v-alert v-if="result" type="success">{{result.status}} · Treasury {{result.treasury_transaction_id}} · Accounting {{result.accounting_posting_reference}}</v-alert></v-card-text><v-card-actions><v-btn color="primary" :disabled="!customerId||!accountId||!invoiceId||amount<=0||allocation<=0" @click="create">Confirm receipt</v-btn></v-card-actions></v-card></template>
